            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Young people, who are still uncertain of their identity, often try on a succession of masks in the hope of finding the one which suits them — the one, in fact, which is not a mask.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Most people are even less original in their dreaming than in their waking life; their dreams are more monotonous than their thoughts and oddly enough, more literary.", Author = "W. H. Auden" },
